args.script:
// xhs-post step 1.5: dual-face auto-signing + logout-fuse block.
// 2026-09-24b: path normalize must eat PROTOCOL-RELATIVE urls too — www pages
// issue XHRs as '//edith.xiaohongshu.com/...'; ^https?: alone misses them, the
// signer then signs host+path -> invalid x-s -> 406 (live-caught on profile
// page: unread_count 406 loop; after fix celestial/lt flips 406->200).
// 2026-09-24 root cause: the publish page misreads unsigned-API 406s
// (upload/creator/permit et al.) as session death and calls
// /sso/logout + /api/galaxy/user/logout ITSELF — the session is killed
// server-side by the page's own logout, then it bounces to /login
// (webBuild 1.30.0 fuse, live-captured via a localStorage request recorder).
// Signing alone is not enough at flow timing: the boot burst fires some
// unsigned calls before this patch lands, so the logout endpoints are also
// answered with a synthetic 200 to defuse the fuse. XHR face unchanged in
// behavior (send-time signer check, __xs_signed counter); fetch face added
// because half the burst goes out via the page's jsvmp fetch wrapper.
(() => {
  if (window.__xs_installed) return 'already';
  window.__xs_installed = true;
  const sign = (u, b) => {
    try {
      if (typeof window._webmsxyw !== 'function') return null;
      const s = String(u);
      if (s.indexOf('xiaohongshu.com') === -1) return null;
      const path = s.replace(/^(https?:)?\/\/[^\/]+/, '');
      let data = b;
      if (typeof b === 'string') { try { data = JSON.parse(b); } catch (e) {} }
      if (b == null || b instanceof FormData || b instanceof ArrayBuffer || b instanceof Blob) data = undefined;
      const sg = window._webmsxyw(path, data);
      return sg && sg['X-s'] ? sg : null;
    } catch (e) { return null; }
  };
  const FUSE = /\/sso\/logout|\/api\/galaxy\/user\/logout/;
  const O = XMLHttpRequest.prototype.open, S = XMLHttpRequest.prototype.setRequestHeader, D = XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.open = function(m, u) {
    this.__xs_u = String(u); this.__xs_m = String(m || 'GET').toUpperCase();
    return O.apply(this, arguments);
  };
  XMLHttpRequest.prototype.setRequestHeader = function(k, v) {
    if (String(k).toLowerCase() === 'x-s') this.__xs_has = true;
    return S.apply(this, arguments);
  };
  XMLHttpRequest.prototype.send = function(b) {
    try {
      if (FUSE.test(this.__xs_u || '')) {
        window.__xs_fuse = (window.__xs_fuse || 0) + 1;
        try {
          Object.defineProperty(this, 'readyState', { value: 4 });
          Object.defineProperty(this, 'status', { value: 200 });
          Object.defineProperty(this, 'responseText', { value: '{"code":0,"success":true}' });
          setTimeout(() => { try {
            this.dispatchEvent(new Event('readystatechange'));
            this.dispatchEvent(new Event('load'));
            this.dispatchEvent(new Event('loadend'));
          } catch (e) {} }, 0);
          return;
        } catch (e) { /* polyfill shape differs: fall through to the wire */ }
      }
      if (!this.__xs_has && this.__xs_u && !(b instanceof FormData)) {
        const sg = sign(this.__xs_u, b);
        if (sg) {
          S.call(this, 'X-s', String(sg['X-s']));
          S.call(this, 'X-t', String(sg['X-t']));
          S.call(this, 'X-Mns', 'unload');
          window.__xs_signed = (window.__xs_signed || 0) + 1;
        }
      }
    } catch (e) {}
    return D.apply(this, arguments);
  };
  const F = window.fetch;
  window.fetch = function(u, o) {
    o = o || {};
    const us = String(typeof u === 'object' && u ? u.url : u);
    if (FUSE.test(us)) {
      window.__xs_fuse = (window.__xs_fuse || 0) + 1;
      return Promise.resolve(new Response(JSON.stringify({ code: 0, success: true }),
        { status: 200, headers: { 'content-type': 'application/json' } }));
    }
    const h = (o.headers || {});
    if (!h['x-s'] && !h['X-s']) {
      const body = (o.body != null && typeof o.body !== 'string') ? undefined : o.body;
      const sg = sign(us, body);
      if (sg) {
        const nh = Object.assign({}, h);
        nh['x-s'] = String(sg['X-s']); nh['x-t'] = String(sg['X-t']);
        o = Object.assign({}, o, { headers: nh });
        window.__xs_signed = (window.__xs_signed || 0) + 1;
      }
    }
    return F.call(this, u, o);
  };
  return 'patched';
})()

// xhs-post step 1.6: engine-side AT renewal (TGC -> service-ticket -> AT).
// 2026-09-24: galaxy sessions (access-token-creator / galaxy_creator_session_id)
// die within minutes-to-days, but the CAS TGC (customer-sso-sid) outlives
// them. The page's own autoLogin fires the same exchange UNSIGNED at boot
// (406, start-up race), so we do it signed. Telemetry only — the verdict gate
// downstream decides the outcome honestly. If {was:401, mint:200, now:200},
// the CURRENT document still holds dirty boot state: re-run the flow once.
(async () => {
  const probe = () => fetch('/api/galaxy/user/info', { credentials: 'include' })
    .then(r => r.status).catch(() => 0);
  const first = await probe();
  if (first === 200) return JSON.stringify({ was: 'alive', mint: null, now: 200 });
  const p = '/api/cas/customer/web/service-ticket';
  const body = { service: 'https://creator.xiaohongshu.com', type: 'tgt' };
  const sg = (typeof window._webmsxyw === 'function') ? window._webmsxyw(p, body) : null;
  let mint = 0;
  try {
    const r = await fetch('https://customer.xiaohongshu.com' + p, {
      method: 'POST', credentials: 'include',
      headers: { 'content-type': 'application/json',
                 'x-s': (sg && sg['X-s']) || '', 'x-t': String((sg && sg['X-t']) || '') },
      body: JSON.stringify(body)
    });
    mint = r.status;
  } catch (e) { mint = 0; }
  const now = await probe();
  return JSON.stringify({ was: first, mint, now, hint: (mint === 200 && now === 200)
    ? 'renewed mid-run; page boot state may be dirty — re-run the flow'
    : 'renewal failed (TGC dead?) — import_curl from a logged-in Chrome' });
})()

// xhs-post step 4: drop the blocking popover (upstream's always-works last resort) and activate the 上传图文 tab. Failure paths throw — an eval's return value is telemetry only, it does not stop the flow
(() => {
  const pop = document.querySelector('div.d-popover');
  if (pop) pop.remove();
  const tabs = [...document.querySelectorAll('div.creator-tab')].map(t => (t.textContent || '').trim());
  const tab = [...document.querySelectorAll('div.creator-tab')].find(t => (t.textContent || '').trim() === '上传图文');
  if (!tab) throw new Error('no 上传图文 tab, tabs=' + JSON.stringify(tabs));
  tab.click();
  return JSON.stringify({ok: true, tabs});
})()

// xhs-post step 5: upload images — data: URL fetch decodes base64 (atob+spread blows the stack on big files), File[] lands in input.files, manual input+change dispatch (JS assignment fires neither by itself). Real-send caveat: a single-File assignment silently no-ops in the engine today (files.length reads back 0); the proven real-page path is the HTTP face POST /session/:id/files — kept here because the flow executor runs in-page and the array face is what the mock dogfood verified
(async () => {
  const ARGS = {{args_json}};
  if (!ARGS.images || !ARGS.images.length) throw new Error('no images');
  window.__xhs_n = ARGS.images.length;
  const inp = document.querySelector('input.upload-input') || document.querySelector('input[type=file]');
  if (!inp) throw new Error('no file input');
  const files = [];
  for (const im of ARGS.images) {
    const type = im.content_type || 'image/png';
    const blob = await (await fetch('data:' + type + ';base64,' + im.content_base64)).blob();
    files.push(new File([blob], im.name || 'image.png', {type}));
  }
  inp.files = files;
  inp.dispatchEvent(new Event('input', {bubbles: true}));
  inp.dispatchEvent(new Event('change', {bubbles: true}));
  if (inp.files.length < files.length) throw new Error('input.files assignment no-op, len=' + inp.files.length);
  return JSON.stringify({ok: true, n: files.length});
})()

// xhs-post step 7: title via native setter + events (React value-tracker bypass), body via tiptap paragraph HTML + input event, then upstream's length guards — over-limit throws so the receipt names the real cause instead of a downstream submit-disabled
(async () => {
  const ARGS = {{args_json}};
  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const out = {};
  const ti = document.querySelector('div.d-input input') || document.querySelector('input[placeholder*="填写标题"]');
  if (!ti) throw new Error('no title input');
  Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(ti, ARGS.title);
  ti.dispatchEvent(new Event('input', {bubbles: true}));
  ti.dispatchEvent(new Event('change', {bubbles: true}));
  out.title_len = ti.value.length;
  out.title_ok = ti.value === String(ARGS.title);
  const ce = document.querySelector('div[role="textbox"][contenteditable="true"]') || document.querySelector('div.tiptap[contenteditable="true"]') || document.querySelector('div.ql-editor');
  if (!ce) throw new Error('no content editor, title_len=' + out.title_len);
  const paras = String(ARGS.content || '').split(/\n+/).filter(Boolean).map(esc);
  const tags = (ARGS.tags || []).map(t => '#' + String(t).replace(/^#/, ''));
  if (tags.length) paras.push(esc(tags.join(' ')));
  ce.innerHTML = paras.map(p => '<p>' + p + '</p>').join('<p><br></p>');
  ce.dispatchEvent(new Event('input', {bubbles: true}));
  out.content_text_len = (ce.innerText || '').length;
  out.title_limit = (document.querySelector('div.title-container div.max_suffix') || {textContent: null}).textContent;
  out.content_limit = (document.querySelector('div.edit-container div.length-error') || {textContent: null}).textContent;
  ti.click(); // upstream stability quirk: re-focus title after body fill
  if (!out.title_ok) throw new Error('title readback mismatch: ' + JSON.stringify(out));
  if (out.title_limit || out.content_limit) throw new Error('length over: title=' + out.title_limit + ' content=' + out.content_limit);
  return JSON.stringify(out);
})()

// xhs-post step 9: publish via the widget's own contract — a bubbling 'publish' CustomEvent on the host (its constructor wires _onPublish → exactly this event), caught by the parent's Vue addEventListener. Even with the #55 upgrade fix the inner button cannot be clicked: webBuild 1.30.0 renders it into a CLOSED shadow root, and this engine's coordinate click faces hit-test via elementFromPoint, which returns the HOST for closed roots (issue #95) — /live takeover clicks land on the host and do nothing. Event dispatch is the only face. Real-send verified 2026-09-20 AND 2026-09-24: dispatch → POST edith /web_api/sns/v2/note 200 → published=true
(() => {
  for (const w of document.querySelectorAll('xhs-publish-btn')) {
    if (w.getAttribute('is-publish') === 'false') continue; // decorative clones
    if (w.getAttribute('submit-disabled') === 'true') continue;
    w.dispatchEvent(new CustomEvent('publish', {bubbles: true, composed: true}));
    return JSON.stringify({ok: true, face: 'widget-event'});
  }
  for (const b of document.querySelectorAll('.publish-page-publish-btn button.bg-red')) {
    if (b.disabled || b.getAttribute('aria-disabled') === 'true') continue;
    b.click();
    return JSON.stringify({ok: true, face: 'legacy-click'});
  }
  throw new Error('no publishable face (wait passed but re-disabled?)');
})()
